var b = $('Task Status Hook').first().json.body || {};
var list = Array.isArray(b.rows) ? b.rows : [];
var ok = ['New', 'In progress', 'Done', 'Dismissed'];
function s(v, n) { return String(v == null ? '' : v).slice(0, n || 300); }
function has(o, k) { return Object.prototype.hasOwnProperty.call(o, k); }
var EX = {};
$('Get Existing').all().forEach(function (i) { var r = i.json; if (r && r.task_key) EX[r.task_key] = r; });
/* Rules (server is the source of truth):
   1. Version gate: only the current hub page (rows tagged v>=2) may write. Old copies of the hub are ignored.
   2. In progress is sticky: background syncs (rows without a note field) can never move an In progress task.
      Only a person's action (Start / Update progress / Back to New / Undo, which always send the note fields) can.
   3. Dismissed: a roll-up reminder dismissed in the task drawer (note = the reminder text; it comes back when the text changes). */
return list.filter(function (r) {
  if (!r || !r.task_key || ok.indexOf(r.status) < 0 || Number(r.v) < 2 || !(Number(r.v) >= 2)) return false;
  var ex = EX[r.task_key];
  if (!has(r, 'note') && ex && ex.status === 'In progress' && r.status !== 'In progress') return false;
  return true;
}).slice(0, 200).map(function (r) {
  var o = { task_key: s(r.task_key, 300), title: s(r.title, 200), ref_table: s(r.ref_table, 40), ref_id: s(r.ref_id, 20), grp: s(r.grp, 60), status: r.status, changed_at: s(r.changed_at, 30) || new Date().toISOString() };
  if (has(r, 'note')) o.note = s(r.note, 80);
  if (has(r, 'note_date')) o.note_date = s(r.note_date, 10);
  if (has(r, 'note_by')) o.note_by = s(r.note_by, 60);
  return { json: o };
});

